edits.old:
$reports=@{};$provenance=@{};$hashes=@{}
foreach($variant in @('baseline','indexed')){
    $evidence=Join-Path $parent ($RunName+'-'+$variant+'/evidence')
    $reportPath=Join-Path $evidence 'full-actor-performance.json'
    $reports[$variant]=Get-Content -LiteralPath $reportPath -Raw|ConvertFrom-Json -AsHashtable
    $provenance[$variant]=Get-Content -LiteralPath (Join-Path $evidence 'provenance.json') -Raw|ConvertFrom-Json -AsHashtable
    $hashes[$variant]=(Get-FileHash -LiteralPath $reportPath -Algorithm SHA256).Hash.ToLowerInvariant()
    if(-not $provenance[$variant].complete_fixed_workload -or $provenance[$variant].status -ne 'complete'){throw 'Incomplete paired workload.'}
    if($provenance[$variant].archive_input_sha256 -ne $pins.archive_sha256){throw 'Pair archive differs.'}
}
$rows=@()
for($i=0;$i -lt 2;$i++){
    $a=$reports.baseline.phases[$i];$b=$reports.indexed.phases[$i]
    $rows+=@{id=$a.id;baseline_scene_p95_ms=$a.scene_cpu_ms.p95;indexed_scene_p95_ms=$b.scene_cpu_ms.p95;signed_scene_p95_ms=$b.scene_cpu_ms.p95-$a.scene_cpu_ms.p95;baseline_min_live=$a.min_live_actors;indexed_min_live=$b.min_live_actors;baseline_stage_calls=$a.stage_calls;indexed_stage_calls=$b.stage_calls}
}
$summary=[ordered]@{schema=1;diagnostic=$true;performance_acceptance=$false;source_archive_sha256=$pins.archive_sha256;workload_hashes=$pins.overlay;measured_scene_sha256=$pins.measured_scene_sha256;report_hashes=$hashes;baseline_failures=$reports.baseline.failures;indexed_failures=$reports.indexed.failures;rows=$rows;note='Single identical-driver pair; normal physics/inputs may diverge. Original16ms gate retained; no causal speed or full-port acceptance claim.'}
[IO.File]::WriteAllText($summaryPath,($summary|ConvertTo-Json -Depth 25),[Text.UTF8Encoding]::new($false))
Write-Output "INDEXED PERFORMANCE PAIR: complete diagnostic; original failure lists retained; $summaryPath"

edits.new:
$helper=Join-Path $PSScriptRoot 'compare-pair.py'
if((Get-FileHash -LiteralPath $helper -Algorithm SHA256).Hash.ToLowerInvariant() -ne $pins.comparison_helper_sha256){throw 'Comparison helper changed.'}
& python $helper --run-name $RunName
if($LASTEXITCODE -ne 0){throw 'Strict diagnostic comparison refused the pair; raw run evidence retained.'}
Write-Output "QUERY RESOURCE PERFORMANCE PAIR: complete diagnostic; original failure lists retained; $summaryPath"
